describe("CompositeDiscountPolicy", () => {
  it("rejects empty policy list", () => {
    expect(() => new CompositeDiscountPolicy([])).toThrow(
      "CompositeDiscountPolicy requires at least one policy",
    );
  });

  describe("sum mode", () => {
    it("sums independent discount computations", () => {
      const p = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "sum",
      );
      // 10% of 10000 = 1000, fixed = 200, sum = 1200
      expect(p.computeDiscountCents(10000)).toBe(1200);
    });

    it("each child receives the original subtotal", () => {
      const p = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50), new PercentageDiscountPolicy(50)],
        "sum",
      );
      // Both get 10000, each returns 5000, sum = 10000
      expect(p.computeDiscountCents(10000)).toBe(10000);
    });

    it("returns 0 for zero subtotal", () => {
      const p = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(p.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const p = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(p.computeDiscountCents(-500)).toBe(0);
    });

    it("defaults to sum mode", () => {
      const p = new CompositeDiscountPolicy([
        new FixedAmountDiscountPolicy(100),
        new FixedAmountDiscountPolicy(200),
      ]);
      expect(p.computeDiscountCents(5000)).toBe(300);
    });
  });

  describe("chain mode", () => {
    it("chains discounts on remaining subtotal", () => {
      const p = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(1000), new PercentageDiscountPolicy(10)],
        "chain",
      );
      // First: fixed 1000 off 10000 → remaining 9000
      // Second: 10% of 9000 = 900
      // Total discount: 1900
      expect(p.computeDiscountCents(10000)).toBe(1900);
    });

    it("ordering matters in chain mode", () => {
      const p1 = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(1000)],
        "chain",
      );
      // First: 10% of 10000 = 1000, remaining 9000
      // Second: fixed 1000, remaining 8000
      // Total: 2000
      expect(p1.computeDiscountCents(10000)).toBe(2000);

      const p2 = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(1000), new PercentageDiscountPolicy(10)],
        "chain",
      );
      // First: fixed 1000, remaining 9000
      // Second: 10% of 9000 = 900
      // Total: 1900
      expect(p2.computeDiscountCents(10000)).toBe(1900);
    });

    it("stops accumulating when remaining hits zero", () => {
      const p = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(100),
          new FixedAmountDiscountPolicy(500),
        ],
        "chain",
      );
      // 100% of 1000 = 1000, remaining 0
      // Fixed 500 applied to 0 → 0
      expect(p.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns 0 for zero subtotal", () => {
      const p = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "chain",
      );
      expect(p.computeDiscountCents(0)).toBe(0);
    });
  });
});

