      computeTaxCents: vi.fn().mockReturnValue(0),
    };
    const cart = new Cart({ taxCalculator: tax, region: "FR" });
    cart.add(mkProduct("a", 1000), 1);
    cart.totals();
    expect(tax.computeTaxCents).toHaveBeenCalledWith(1000, "FR");
  });
});

describe("Cart – checkout()", () => {
  it("checkout without collaborators returns sync totals", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 2);
    const result = await cart.checkout();
    expect(result.totals.subtotalCents).toBe(2000);
    expect(result.lines).toHaveLength(1);
  });

  it("refreshes prices via priceFetcher", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 1);
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(1500),
    };

    const result = await cart.checkout({ priceFetcher });
    expect(result.totals.subtotalCents).toBe(1500);
    expect(priceFetcher.fetchPriceCents).toHaveBeenCalledWith("a");
  });

  it("checks inventory and passes on available", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 2);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 10 }),
    };

    const result = await cart.checkout({ inventoryChecker });
    expect(result.totals.subtotalCents).toBe(2000);
    expect(inventoryChecker.check).toHaveBeenCalledWith("a", 2);
  });

  it("throws InventoryError when not available", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 5);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: false,
        availableQuantity: 2,
        reason: "only 2 left",
      }),
    };

    try {
      await cart.checkout({ inventoryChecker });
      expect.fail("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const ie = err as InventoryError;
      expect(ie.productId).toBe("a");
      expect(ie.requested).toBe(5);
      expect(ie.available).toBe(2);
      expect(ie.message).toBe("only 2 left");
    }
  });

  it("throws InventoryError on partial-stock denial (available but quantity < requested)", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 5);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 3,
      }),
    };

    await expect(cart.checkout({ inventoryChecker })).rejects.toThrow(InventoryError);
  });

  it("uses asyncTaxProvider for tax computation", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 10000), 1);
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.10),
    };

    const result = await cart.checkout({ asyncTaxProvider });
    expect(result.totals.taxCents).toBe(1000);
    expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US");
  });

  it("combines discount + async tax + shipping", async () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(2000),
    };
    const shipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(500),
    };
    const cart = new Cart({ discountPolicy: discount, shippingCalculator: shipping });
    cart.add(mkProduct("a", 10000), 1);

    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.10),
    };
    const result = await cart.checkout({ asyncTaxProvider });

    // subtotal 10000, discount 2000, discounted 8000
    // tax: 10% of 8000 = 800
    // shipping: 500
    expect(result.totals.subtotalCents).toBe(10000);
    expect(result.totals.discountCents).toBe(2000);
    expect(result.totals.taxCents).toBe(800);
    expect(result.totals.shippingCents).toBe(500);
    expect(result.totals.totalCents).toBe(8000 + 800 + 500);
  });

  it("propagates asyncTaxProvider rejection", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 1);
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
    };

    await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow("tax service down");
  });

  it("propagates priceFetcher rejection", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 1);
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("price service down")),
    };

    await expect(cart.checkout({ priceFetcher })).rejects.toThrow("price service down");
  });

  it("inventory check runs after price refresh", async () => {
    const callOrder: string[] = [];
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 1);

    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockImplementation(async () => {
        callOrder.push("fetch");
        return 1500;
      }),
    };
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockImplementation(async () => {
        callOrder.push("check");
        return { available: true } as InventoryDecision;
      }),
    };

    await cart.checkout({ priceFetcher, inventoryChecker });
    expect(callOrder).toEqual(["fetch", "check"]);
  });

  it("first inventory denial wins for multiple lines", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 1);
    cart.add(mkProduct("b", 2000), 1);

    const inventoryChecker: InventoryChecker = {
      check: vi.fn()
        .mockResolvedValueOnce({ available: false, reason: "a is out" } as InventoryDecision)
        .mockResolvedValueOnce({ available: true } as InventoryDecision),
    };

    try {
      await cart.checkout({ inventoryChecker });
      expect.fail("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      // Only first product checked before throwing
      expect(inventoryChecker.check).toHaveBeenCalledTimes(1);
    }
  });

  it("checkout returns lines snapshot (possibly with refreshed prices)", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 2);
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(1500),
    };

    const result = await cart.checkout({ priceFetcher });
    expect(result.lines[0].product.unitPriceCents).toBe(1500);
    // Original cart is not mutated
    expect(cart.snapshot()[0].product.unitPriceCents).toBe(1000);
  });
});

import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const policy = new NoDiscountPolicy();

  it("returns 0 for a positive subtotal", () => {
    expect(policy.computeDiscountCents(10000)).toBe(0);
  });

  it("returns 0 for zero subtotal", () => {
    expect(policy.computeDiscountCents(0)).toBe(0);
  });

  it("returns 0 for negative subtotal", () => {
    expect(policy.computeDiscountCents(-500)).toBe(0);
  });
});

describe("PercentageDiscountPolicy", () => {
  it("rejects negative percent", () => {
    expect(() => new PercentageDiscountPolicy(-1)).toThrow(RangeError);
  });

  it("rejects percent > 100", () => {
    expect(() => new PercentageDiscountPolicy(101)).toThrow(RangeError);
  });

  it("rejects NaN", () => {
    expect(() => new PercentageDiscountPolicy(NaN)).toThrow(RangeError);
  });

  it("rejects Infinity", () => {
    expect(() => new PercentageDiscountPolicy(Infinity)).toThrow(RangeError);
  });

  it("accepts 0%", () => {
    const p = new PercentageDiscountPolicy(0);
    expect(p.computeDiscountCents(10000)).toBe(0);
  });

  it("accepts 100%", () => {
    const p = new PercentageDiscountPolicy(100);
    expect(p.computeDiscountCents(10000)).toBe(10000);
  });

  it("computes 10% of 10000 = 1000", () => {
    const p = new PercentageDiscountPolicy(10);
    expect(p.computeDiscountCents(10000)).toBe(1000);
  });

  it("rounds down to nearest cent", () => {
    const p = new PercentageDiscountPolicy(33);
    // 33% of 100 = 33.0 exactly
    expect(p.computeDiscountCents(100)).toBe(33);
    // 33% of 101 = 33.33 → floor → 33
    expect(p.computeDiscountCents(101)).toBe(33);
  });

  it("returns 0 for zero subtotal", () => {
    const p = new PercentageDiscountPolicy(50);
    expect(p.computeDiscountCents(0)).toBe(0);
  });

  it("returns 0 for negative subtotal", () => {
    const p = new PercentageDiscountPolicy(50);
    expect(p.computeDiscountCents(-1000)).toBe(0);
  });

  it("handles very large subtotal", () => {
    const p = new PercentageDiscountPolicy(15);
    expect(p.computeDiscountCents(999_999_999)).toBe(Math.floor(999_999_999 * 15 / 100));
  });
});

describe("FixedAmountDiscountPolicy", () => {
  it("rejects negative amount", () => {
    expect(() => new FixedAmountDiscountPolicy(-1)).toThrow(RangeError);
  });

  it("rejects non-integer amount", () => {
    expect(() => new FixedAmountDiscountPolicy(10.5)).toThrow(RangeError);
  });

  it("accepts zero", () => {
    const p = new FixedAmountDiscountPolicy(0);
    expect(p.computeDiscountCents(5000)).toBe(0);
  });

  it("returns the fixed amount when subtotal exceeds it", () => {
    const p = new FixedAmountDiscountPolicy(500);
    expect(p.computeDiscountCents(10000)).toBe(500);
  });

  it("caps at subtotal when discount exceeds subtotal", () => {
    const p = new FixedAmountDiscountPolicy(5000);
    expect(p.computeDiscountCents(3000)).toBe(3000);
  });

  it("returns 0 for zero subtotal", () => {
    const p = new FixedAmountDiscountPolicy(500);
    expect(p.computeDiscountCents(0)).toBe(0);
  });

  it("returns 0 for negative subtotal", () => {
    const p = new FixedAmountDiscountPolicy(500);
    expect(p.computeDiscountCents(-100)).toBe(0);
  });
});

describe("CompositeDiscountPolicy", () => {
  it("rejects empty policy list", () => {
    expect(() => new CompositeDiscountPolicy([])).toThrow(
      "CompositeDiscountPolicy requires at least one policy",
    );
  });

  describe("sum mode", () => {
    it("sums independent discount computations", () => {
      const p = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "sum",
      );
      // 10% of 10000 = 1000, fixed = 200, sum = 1200
      expect(p.computeDiscountCents(10000)).toBe(1200);
    });

    it("each child receives the original subtotal", () => {
      const p = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50), new PercentageDiscountPolicy(50)],
        "sum",
      );
      // Both get 10000, each returns 5000, sum = 10000
      expect(p.computeDiscountCents(10000)).toBe(10000);
    });

    it("returns 0 for zero subtotal", () => {
      const p = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(p.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const p = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(p.computeDiscountCents(-500)).toBe(0);
    });

    it("defaults to sum mode", () => {
      const p = new CompositeDiscountPolicy([
        new FixedAmountDiscountPolicy(100),
        new FixedAmountDiscountPolicy(200),
      ]);
      expect(p.computeDiscountCents(5000)).toBe(300);
    });
  });

  describe("chain mode", () => {
    it("chains discounts on remaining subtotal", () => {
      const p = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(1000), new PercentageDiscountPolicy(10)],
        "chain",
      );
      // First: fixed 1000 off 10000 → remaining 9000
      // Second: 10% of 9000 = 900
      // Total discount: 1900
      expect(p.computeDiscountCents(10000)).toBe(1900);
    });

    it("ordering matters in chain mode", () => {
      const p1 = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(1000)],
        "chain",
      );
      // First: 10% of 10000 = 1000, remaining 9000
      // Second: fixed 1000, remaining 8000
      // Total: 2000
      expect(p1.computeDiscountCents(10000)).toBe(2000);

      const p2 = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(1000), new PercentageDiscountPolicy(10)],
        "chain",
      );
      // First: fixed 1000, remaining 9000
      // Second: 10% of 9000 = 900
      // Total: 1900
      expect(p2.computeDiscountCents(10000)).toBe(1900);
    });

    it("stops accumulating when remaining hits zero", () => {
      const p = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(100),
          new FixedAmountDiscountPolicy(500),
        ],
        "chain",
      );
      // 100% of 1000 = 1000, remaining 0
      // Fixed 500 applied to 0 → 0
      expect(p.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns 0 for zero subtotal", () => {
      const p = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "chain",
      );
      expect(p.computeDiscountCents(0)).toBe(0);
    });
  });
});

