describe("Cart – line management", () => {
  it("add() creates a new line", () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 2);
    expect(cart.itemCount).toBe(2);
  });

  it("add() merges quantity for same product", () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 2);
    cart.add(mkProduct("a", 1000), 3);
    expect(cart.itemCount).toBe(5);
  });

  it("add() rejects non-positive quantity", () => {
    const cart = new Cart();
    expect(() => cart.add(mkProduct("a", 1000), 0)).toThrow(RangeError);
    expect(() => cart.add(mkProduct("a", 1000), -1)).toThrow(RangeError);
  });

  it("add() rejects non-integer quantity", () => {
    const cart = new Cart();
    expect(() => cart.add(mkProduct("a", 1000), 1.5)).toThrow(RangeError);
  });

  it("add() rejects negative unitPriceCents", () => {
    const cart = new Cart();
    expect(() => cart.add(mkProduct("a", -1), 1)).toThrow(RangeError);
  });

  it("remove() returns true for existing product", () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 1);
    expect(cart.remove("a")).toBe(true);
    expect(cart.itemCount).toBe(0);
  });

  it("remove() returns false for unknown product", () => {
    const cart = new Cart();
    expect(cart.remove("nonexistent")).toBe(false);
  });

  it("updateQuantity() changes the quantity", () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 5);
    cart.updateQuantity("a", 3);
    expect(cart.itemCount).toBe(3);
  });

  it("updateQuantity(0) removes the line", () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 5);
    cart.updateQuantity("a", 0);
    expect(cart.itemCount).toBe(0);
  });

  it("updateQuantity() throws for unknown product", () => {
    const cart = new Cart();
    expect(() => cart.updateQuantity("x", 1)).toThrow("Product x is not in the cart");
  });

  it("updateQuantity() rejects negative quantity", () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 1);
    expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
  });

  it("updateQuantity() rejects non-integer quantity", () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 1);
    expect(() => cart.updateQuantity("a", 1.5)).toThrow(RangeError);
  });

  it("clear() empties the cart", () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 1);
    cart.add(mkProduct("b", 2000), 2);
    cart.clear();
    expect(cart.itemCount).toBe(0);
  });

  it("snapshot() returns deep copies", () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 1);
    const snap = cart.snapshot();
    snap[0].quantity = 999;
    snap[0].product.unitPriceCents = 999;
    expect(cart.itemCount).toBe(1);
    expect(cart.snapshot()[0].product.unitPriceCents).toBe(1000);
  });
