  });

  describe("sum mode", () => {
    it("sums independent discount computations", () => {
      const p = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "sum",
      );
      // 10% of 10000 = 1000, fixed = 200, sum = 1200
      expect(p.computeDiscountCents(10000)).toBe(1200);
    });

    it("each child receives the original subtotal", () => {
      const p = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50), new PercentageDiscountPolicy(50)],
        "sum",
      );
      // Both get 10000, each returns 5000, sum = 10000
      expect(p.computeDiscountCents(10000)).toBe(10000);
    });

    it("returns 0 for zero subtotal", () => {
      const p = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
