describe("Cart – checkout()", () => {
  it("checkout without collaborators returns sync totals", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 2);
    const result = await cart.checkout();
    expect(result.totals.subtotalCents).toBe(2000);
    expect(result.lines).toHaveLength(1);
  });

  it("refreshes prices via priceFetcher", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 1);
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(1500),
    };

    const result = await cart.checkout({ priceFetcher });
    expect(result.totals.subtotalCents).toBe(1500);
    expect(priceFetcher.fetchPriceCents).toHaveBeenCalledWith("a");
  });

  it("checks inventory and passes on available", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 2);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 10 }),
    };

    const result = await cart.checkout({ inventoryChecker });
    expect(result.totals.subtotalCents).toBe(2000);
    expect(inventoryChecker.check).toHaveBeenCalledWith("a", 2);
  });

  it("throws InventoryError when not available", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 5);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: false,
        availableQuantity: 2,
        reason: "only 2 left",
      }),
    };

    try {
      await cart.checkout({ inventoryChecker });
      expect.fail("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const ie = err as InventoryError;
      expect(ie.productId).toBe("a");
      expect(ie.requested).toBe(5);
      expect(ie.available).toBe(2);
      expect(ie.message).toBe("only 2 left");
    }
  });

  it("throws InventoryError on partial-stock denial (available but quantity < requested)", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 5);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 3,
      }),
    };

    await expect(cart.checkout({ inventoryChecker })).rejects.toThrow(InventoryError);
  });

  it("uses asyncTaxProvider for tax computation", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 10000), 1);
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.10),
    };

    const result = await cart.checkout({ asyncTaxProvider });
    expect(result.totals.taxCents).toBe(1000);
    expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US");
  });

  it("combines discount + async tax + shipping", async () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(2000),
    };
    const shipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(500),
    };
    const cart = new Cart({ discountPolicy: discount, shippingCalculator: shipping });
    cart.add(mkProduct("a", 10000), 1);

    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.10),
    };
    const result = await cart.checkout({ asyncTaxProvider });

    // subtotal 10000, discount 2000, discounted 8000
    // tax: 10% of 8000 = 800
    // shipping: 500
    expect(result.totals.subtotalCents).toBe(10000);
    expect(result.totals.discountCents).toBe(2000);
    expect(result.totals.taxCents).toBe(800);
    expect(result.totals.shippingCents).toBe(500);
    expect(result.totals.totalCents).toBe(8000 + 800 + 500);
  });

  it("propagates asyncTaxProvider rejection", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 1);
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
    };

    await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow("tax service down");
  });

  it("propagates priceFetcher rejection", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 1);
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("price service down")),
    };

    await expect(cart.checkout({ priceFetcher })).rejects.toThrow("price service down");
  });

  it("inventory check runs after price refresh", async () => {
    const callOrder: string[] = [];
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 1);

    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockImplementation(async () => {
        callOrder.push("fetch");
        return 1500;
      }),
    };
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockImplementation(async () => {
        callOrder.push("check");
        return { available: true } as InventoryDecision;
      }),
    };

    await cart.checkout({ priceFetcher, inventoryChecker });
    expect(callOrder).toEqual(["fetch", "check"]);
  });

  it("first inventory denial wins for multiple lines", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 1);
    cart.add(mkProduct("b", 2000), 1);

    const inventoryChecker: InventoryChecker = {
      check: vi.fn()
        .mockResolvedValueOnce({ available: false, reason: "a is out" } as InventoryDecision)
        .mockResolvedValueOnce({ available: true } as InventoryDecision),
    };

    try {
      await cart.checkout({ inventoryChecker });
      expect.fail("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      // Only first product checked before throwing
      expect(inventoryChecker.check).toHaveBeenCalledTimes(1);
    }
  });

  it("checkout returns lines snapshot (possibly with refreshed prices)", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 2);
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(1500),
    };

    const result = await cart.checkout({ priceFetcher });
    expect(result.lines[0].product.unitPriceCents).toBe(1500);
    // Original cart is not mutated
    expect(cart.snapshot()[0].product.unitPriceCents).toBe(1000);
  });
});
"}

