toolArgs.file_text:
import { describe, it, expect, vi } from "vitest";
import {
  NoTaxCalculator,
  RegionalTaxCalculator,
  AsyncTaxCalculator,
  totalLineWeightGrams,
  type AsyncTaxRateProvider,
} from "../src/tax.ts";
import type { CartLine } from "../src/product.ts";

describe("NoTaxCalculator", () => {
  const calc = new NoTaxCalculator();

  it("returns 0 for any input", () => {
    expect(calc.computeTaxCents(10000, "US")).toBe(0);
    expect(calc.computeTaxCents(0, "FR")).toBe(0);
    expect(calc.computeTaxCents(-100, "GB")).toBe(0);
  });
});

describe("RegionalTaxCalculator", () => {
  it("rejects default rate < 0", () => {
    expect(() => new RegionalTaxCalculator({}, -0.01)).toThrow(RangeError);
  });

  it("rejects default rate > 1", () => {
    expect(() => new RegionalTaxCalculator({}, 1.01)).toThrow(RangeError);
  });

  it("rejects NaN default rate", () => {
    expect(() => new RegionalTaxCalculator({}, NaN)).toThrow(RangeError);
  });

  it("rejects invalid region rate", () => {
    expect(() => new RegionalTaxCalculator({ "US": 1.5 })).toThrow(RangeError);
  });

  it("rejects negative region rate", () => {
    expect(() => new RegionalTaxCalculator({ "US": -0.1 })).toThrow(RangeError);
  });

  it("uses the region rate when available", () => {
    const calc = new RegionalTaxCalculator({ "US": 0.08, "FR": 0.20 });
    expect(calc.computeTaxCents(10000, "US")).toBe(800);
    expect(calc.computeTaxCents(10000, "FR")).toBe(2000);
  });

  it("falls back to the default rate for unknown regions", () => {
    const calc = new RegionalTaxCalculator({ "US": 0.08 }, 0.05);
    expect(calc.computeTaxCents(10000, "JP")).toBe(500);
  });

  it("default rate defaults to 0", () => {
    const calc = new RegionalTaxCalculator({ "US": 0.08 });
    expect(calc.computeTaxCents(10000, "JP")).toBe(0);
  });

  it("rounds down to nearest cent", () => {
    const calc = new RegionalTaxCalculator({ "US": 0.0875 });
    // 0.0875 * 9999 = 874.9125 → 874
    expect(calc.computeTaxCents(9999, "US")).toBe(874);
  });

  it("returns 0 for zero taxable amount", () => {
    const calc = new RegionalTaxCalculator({ "US": 0.10 });
    expect(calc.computeTaxCents(0, "US")).toBe(0);
  });

  it("returns 0 for negative taxable amount", () => {
    const calc = new RegionalTaxCalculator({ "US": 0.10 });
    expect(calc.computeTaxCents(-500, "US")).toBe(0);
  });

  it("accepts rate of exactly 0", () => {
    const calc = new RegionalTaxCalculator({ "US": 0 });
    expect(calc.computeTaxCents(10000, "US")).toBe(0);
  });

  it("accepts rate of exactly 1", () => {
    const calc = new RegionalTaxCalculator({ "US": 1 });
    expect(calc.computeTaxCents(10000, "US")).toBe(10000);
  });
});

describe("AsyncTaxCalculator", () => {
  it("returns tax based on provider rate", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.10),
    };
    const calc = new AsyncTaxCalculator(provider);
    expect(await calc.computeTaxCents(10000, "US")).toBe(1000);
    expect(provider.getRate).toHaveBeenCalledWith("US");
  });

  it("rounds down to nearest cent", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.0875),
    };
    const calc = new AsyncTaxCalculator(provider);
    expect(await calc.computeTaxCents(9999, "US")).toBe(874);
  });

  it("returns 0 for zero taxable amount without calling provider", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.10),
    };
    const calc = new AsyncTaxCalculator(provider);
    expect(await calc.computeTaxCents(0, "US")).toBe(0);
  });

  it("returns 0 for negative taxable amount", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.10),
    };
    const calc = new AsyncTaxCalculator(provider);
    expect(await calc.computeTaxCents(-100, "US")).toBe(0);
  });

  it("rejects rate > 1 from provider", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(1.5),
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(10000, "US")).rejects.toThrow(RangeError);
  });

  it("rejects negative rate from provider", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(-0.1),
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(10000, "US")).rejects.toThrow(RangeError);
  });

  it("rejects NaN rate from provider", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(NaN),
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(10000, "US")).rejects.toThrow(RangeError);
  });

  it("propagates provider rejection", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("network failure")),
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(10000, "US")).rejects.toThrow("network failure");
  });
});

describe("totalLineWeightGrams", () => {
  it("sums weight * quantity across lines", () => {
    const lines: CartLine[] = [
      { product: { id: "a", name: "A", unitPriceCents: 100, weightGrams: 500 }, quantity: 2 },
      { product: { id: "b", name: "B", unitPriceCents: 200, weightGrams: 300 }, quantity: 3 },
    ];
    expect(totalLineWeightGrams(lines)).toBe(500 * 2 + 300 * 3);
  });

  it("treats missing weightGrams as 0", () => {
    const lines: CartLine[] = [
      { product: { id: "a", name: "A", unitPriceCents: 100 }, quantity: 5 },
    ];
    expect(totalLineWeightGrams(lines)).toBe(0);
  });

  it("returns 0 for empty array", () => {
    expect(totalLineWeightGrams([])).toBe(0);
  });
});

