toolArgs.file_text:
import { describe, it, expect } from "vitest";
import {
  FreeShippingCalculator,
  FlatShippingCalculator,
  WeightBasedShippingCalculator,
} from "../src/shipping.ts";
import type { CartLine } from "../src/product.ts";

const line = (id: string, weightGrams: number, qty: number): CartLine => ({
  product: { id, name: id, unitPriceCents: 1000, weightGrams },
  quantity: qty,
});

const noWeightLine = (id: string, qty: number): CartLine => ({
  product: { id, name: id, unitPriceCents: 1000 },
  quantity: qty,
});

describe("FreeShippingCalculator", () => {
  const calc = new FreeShippingCalculator();

  it("returns 0 for non-empty cart", () => {
    expect(calc.computeShippingCents([line("a", 500, 1)], 5000)).toBe(0);
  });

  it("returns 0 for empty cart", () => {
    expect(calc.computeShippingCents([], 0)).toBe(0);
  });
});

describe("FlatShippingCalculator", () => {
  it("rejects negative flatCents", () => {
    expect(() => new FlatShippingCalculator(-1)).toThrow(RangeError);
  });

  it("rejects non-integer flatCents", () => {
    expect(() => new FlatShippingCalculator(10.5)).toThrow(RangeError);
  });

  it("rejects negative freeOverCents", () => {
    expect(() => new FlatShippingCalculator(500, -1)).toThrow(RangeError);
  });

  it("rejects non-integer freeOverCents", () => {
    expect(() => new FlatShippingCalculator(500, 10.5)).toThrow(RangeError);
  });

  it("returns the flat fee for a non-empty cart", () => {
    const calc = new FlatShippingCalculator(999);
    expect(calc.computeShippingCents([line("a", 500, 1)], 5000)).toBe(999);
  });

  it("returns 0 for an empty cart", () => {
    const calc = new FlatShippingCalculator(999);
    expect(calc.computeShippingCents([], 5000)).toBe(0);
  });

  it("returns 0 when subtotal >= freeOverCents", () => {
    const calc = new FlatShippingCalculator(999, 5000);
    expect(calc.computeShippingCents([line("a", 500, 1)], 5000)).toBe(0);
    expect(calc.computeShippingCents([line("a", 500, 1)], 6000)).toBe(0);
  });

  it("returns flat fee when subtotal < freeOverCents", () => {
    const calc = new FlatShippingCalculator(999, 5000);
    expect(calc.computeShippingCents([line("a", 500, 1)], 4999)).toBe(999);
  });

  it("accepts zero flatCents", () => {
    const calc = new FlatShippingCalculator(0);
    expect(calc.computeShippingCents([line("a", 500, 1)], 1000)).toBe(0);
  });

  it("accepts zero freeOverCents (always free for non-negative subtotal)", () => {
    const calc = new FlatShippingCalculator(999, 0);
    expect(calc.computeShippingCents([line("a", 500, 1)], 0)).toBe(0);
    expect(calc.computeShippingCents([line("a", 500, 1)], 100)).toBe(0);
  });
});

describe("WeightBasedShippingCalculator", () => {
  it("rejects empty brackets", () => {
    expect(() => new WeightBasedShippingCalculator([])).toThrow(
      "at least one weight bracket is required",
    );
  });

  it("rejects bracket with non-positive upToGrams", () => {
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 100 }]),
    ).toThrow(RangeError);
  });

  it("rejects bracket with negative costCents", () => {
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: 500, costCents: -1 }]),
    ).toThrow(RangeError);
  });

  it("rejects non-integer upToGrams", () => {
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: 1.5, costCents: 100 }]),
    ).toThrow(RangeError);
  });

  it("rejects non-integer costCents", () => {
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: 500, costCents: 1.5 }]),
    ).toThrow(RangeError);
  });

  it("rejects negative overflowCostCents", () => {
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: 500, costCents: 100 }], -1),
    ).toThrow(RangeError);
  });

  it("rejects non-integer overflowCostCents", () => {
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: 500, costCents: 100 }], 1.5),
    ).toThrow(RangeError);
  });

  it("returns 0 for empty cart", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 1000, costCents: 500 },
    ]);
    expect(calc.computeShippingCents([], 5000)).toBe(0);
  });

  it("returns 0 for items with no weight", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 1000, costCents: 500 },
    ]);
    expect(calc.computeShippingCents([noWeightLine("a", 2)], 5000)).toBe(0);
  });

  it("selects the correct bracket", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
      { upToGrams: 2000, costCents: 900 },
    ]);
    expect(calc.computeShippingCents([line("a", 400, 1)], 5000)).toBe(300);
    expect(calc.computeShippingCents([line("a", 500, 1)], 5000)).toBe(300); // boundary: exactly at upToGrams
    expect(calc.computeShippingCents([line("a", 501, 1)], 5000)).toBe(600);
    expect(calc.computeShippingCents([line("a", 1000, 1)], 5000)).toBe(600);
    expect(calc.computeShippingCents([line("a", 1001, 1)], 5000)).toBe(900);
  });

  it("sorts brackets regardless of input order", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 2000, costCents: 900 },
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
    ]);
    expect(calc.computeShippingCents([line("a", 400, 1)], 5000)).toBe(300);
  });

  it("uses overflow cost when weight exceeds all brackets", () => {
    const calc = new WeightBasedShippingCalculator(
      [{ upToGrams: 500, costCents: 300 }],
      1500,
    );
    expect(calc.computeShippingCents([line("a", 600, 1)], 5000)).toBe(1500);
  });

  it("falls back to heaviest bracket cost when no overflow specified", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
    ]);
    expect(calc.computeShippingCents([line("a", 5000, 1)], 5000)).toBe(600);
  });

  it("sums weight across multiple lines", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
    ]);
    // 200 * 2 + 300 * 1 = 700, falls into second bracket
    const lines = [line("a", 200, 2), line("b", 300, 1)];
    expect(calc.computeShippingCents(lines, 5000)).toBe(600);
  });
});

