toolArgs.file_text:
import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import { InventoryError } from "../src/inventory.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";
import type { Product, CartLine } from "../src/product.ts";
import type {
  PriceFetcher,
  InventoryChecker,
  InventoryDecision,
} from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";

const mkProduct = (id: string, price: number, weight?: number): Product => ({
  id,
  name: `Product ${id}`,
  unitPriceCents: price,
  weightGrams: weight,
});

describe("Cart – line management", () => {
  it("add() creates a new line", () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 2);
    expect(cart.itemCount).toBe(2);
  });

  it("add() merges quantity for same product", () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 2);
    cart.add(mkProduct("a", 1000), 3);
    expect(cart.itemCount).toBe(5);
  });

  it("add() rejects non-positive quantity", () => {
    const cart = new Cart();
    expect(() => cart.add(mkProduct("a", 1000), 0)).toThrow(RangeError);
    expect(() => cart.add(mkProduct("a", 1000), -1)).toThrow(RangeError);
  });

  it("add() rejects non-integer quantity", () => {
    const cart = new Cart();
    expect(() => cart.add(mkProduct("a", 1000), 1.5)).toThrow(RangeError);
  });

  it("add() rejects negative unitPriceCents", () => {
    const cart = new Cart();
    expect(() => cart.add(mkProduct("a", -1), 1)).toThrow(RangeError);
  });

  it("remove() returns true for existing product", () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 1);
    expect(cart.remove("a")).toBe(true);
    expect(cart.itemCount).toBe(0);
  });

  it("remove() returns false for unknown product", () => {
    const cart = new Cart();
    expect(cart.remove("nonexistent")).toBe(false);
  });

  it("updateQuantity() changes the quantity", () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 5);
    cart.updateQuantity("a", 3);
    expect(cart.itemCount).toBe(3);
  });

  it("updateQuantity(0) removes the line", () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 5);
    cart.updateQuantity("a", 0);
    expect(cart.itemCount).toBe(0);
  });

  it("updateQuantity() throws for unknown product", () => {
    const cart = new Cart();
    expect(() => cart.updateQuantity("x", 1)).toThrow("Product x is not in the cart");
  });

  it("updateQuantity() rejects negative quantity", () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 1);
    expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
  });

  it("updateQuantity() rejects non-integer quantity", () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 1);
    expect(() => cart.updateQuantity("a", 1.5)).toThrow(RangeError);
  });

  it("clear() empties the cart", () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 1);
    cart.add(mkProduct("b", 2000), 2);
    cart.clear();
    expect(cart.itemCount).toBe(0);
  });

  it("snapshot() returns deep copies", () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 1);
    const snap = cart.snapshot();
    snap[0].quantity = 999;
    snap[0].product.unitPriceCents = 999;
    expect(cart.itemCount).toBe(1);
    expect(cart.snapshot()[0].product.unitPriceCents).toBe(1000);
  });
});

describe("Cart – totals pipeline", () => {
  it("computes subtotal from lines", () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 2);
    cart.add(mkProduct("b", 500), 3);
    const t = cart.totals();
    expect(t.subtotalCents).toBe(3500);
    expect(t.discountCents).toBe(0);
    expect(t.taxCents).toBe(0);
    expect(t.shippingCents).toBe(0);
    expect(t.totalCents).toBe(3500);
  });

  it("empty cart has all zeros", () => {
    const cart = new Cart();
    const t = cart.totals();
    expect(t.subtotalCents).toBe(0);
    expect(t.totalCents).toBe(0);
  });

  it("applies discount, then tax on discounted subtotal", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(1000),
    };
    const tax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(200),
    };
    const cart = new Cart({ discountPolicy: discount, taxCalculator: tax });
    cart.add(mkProduct("a", 5000), 1);

    const t = cart.totals();
    expect(t.subtotalCents).toBe(5000);
    expect(t.discountCents).toBe(1000);
    // Tax is called with discounted subtotal (4000)
    expect(tax.computeTaxCents).toHaveBeenCalledWith(4000, "US");
    expect(t.taxCents).toBe(200);
    expect(t.totalCents).toBe(4000 + 200);
  });

  it("shipping uses discounted subtotal", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(2000),
    };
    const shipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(500),
    };
    const cart = new Cart({
      discountPolicy: discount,
      shippingCalculator: shipping,
    });
    cart.add(mkProduct("a", 5000), 1);

    const t = cart.totals();
    expect(shipping.computeShippingCents).toHaveBeenCalledWith(
      expect.any(Array),
      3000, // discounted subtotal
    );
    expect(t.shippingCents).toBe(500);
    expect(t.totalCents).toBe(3000 + 500);
  });

  it("clamps discount to [0, subtotal]", () => {
    const overDiscount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(99999),
    };
    const cart = new Cart({ discountPolicy: overDiscount });
    cart.add(mkProduct("a", 1000), 1);
    const t = cart.totals();
    expect(t.discountCents).toBe(1000); // clamped to subtotal
    expect(t.totalCents).toBe(0);
  });

  it("clamps negative discount to 0", () => {
    const negDiscount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(-500),
    };
    const cart = new Cart({ discountPolicy: negDiscount });
    cart.add(mkProduct("a", 1000), 1);
    const t = cart.totals();
    expect(t.discountCents).toBe(0);
    expect(t.totalCents).toBe(1000);
  });

  it("clamps negative tax to 0", () => {
    const tax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(-100),
    };
    const cart = new Cart({ taxCalculator: tax });
    cart.add(mkProduct("a", 1000), 1);
    expect(cart.totals().taxCents).toBe(0);
  });

  it("clamps negative shipping to 0", () => {
    const shipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(-100),
    };
    const cart = new Cart({ shippingCalculator: shipping });
    cart.add(mkProduct("a", 1000), 1);
    expect(cart.totals().shippingCents).toBe(0);
  });

  it("uses custom region for tax", () => {
    const tax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(0),
    };
    const cart = new Cart({ taxCalculator: tax, region: "FR" });
    cart.add(mkProduct("a", 1000), 1);
    cart.totals();
    expect(tax.computeTaxCents).toHaveBeenCalledWith(1000, "FR");
  });
});

describe("Cart – checkout()", () => {
  it("checkout without collaborators returns sync totals", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 2);
    const result = await cart.checkout();
    expect(result.totals.subtotalCents).toBe(2000);
    expect(result.lines).toHaveLength(1);
  });

  it("refreshes prices via priceFetcher", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 1);
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(1500),
    };

    const result = await cart.checkout({ priceFetcher });
    expect(result.totals.subtotalCents).toBe(1500);
    expect(priceFetcher.fetchPriceCents).toHaveBeenCalledWith("a");
  });

  it("checks inventory and passes on available", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 2);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 10 }),
    };

    const result = await cart.checkout({ inventoryChecker });
