+describe("Cart – totals pipeline", () => {
+  it("computes subtotal from lines", () => {
+    const cart = new Cart();
+    cart.add(mkProduct("a", 1000), 2);
+    cart.add(mkProduct("b", 500), 3);
+    const t = cart.totals();
+    expect(t.subtotalCents).toBe(3500);
+    expect(t.discountCents).toBe(0);
+    expect(t.taxCents).toBe(0);
+    expect(t.shippingCents).toBe(0);
+    expect(t.totalCents).toBe(3500);
+  });
+
+  it("empty cart has all zeros", () => {
+    const cart = new Cart();
+    const t = cart.totals();
+    expect(t.subtotalCents).toBe(0);
+    expect(t.totalCents).toBe(0);
+  });
+
+  it("applies discount, then tax on discounted subtotal", () => {
+    const discount: DiscountPolicy = {
+      computeDiscountCents: vi.fn().mockReturnValue(1000),
+    };
+    const tax: TaxCalculator = {
+      computeTaxCents: vi.fn().mockReturnValue(200),
+    };
+    const cart = new Cart({ discountPolicy: discount, taxCalculator: tax });
+    cart.add(mkProduct("a", 5000), 1);
+
+    const t = cart.totals();
+    expect(t.subtotalCents).toBe(5000);
+    expect(t.discountCents).toBe(1000);
+    // Tax is called with discounted subtotal (4000)
+    expect(tax.computeTaxCents).toHaveBeenCalledWith(4000, "US");
+    expect(t.taxCents).toBe(200);
+    expect(t.totalCents).toBe(4000 + 200);
+  });
+
+  it("shipping uses discounted subtotal", () => {
+    const discount: DiscountPolicy = {
+      computeDiscountCents: vi.fn().mockReturnValue(2000),
+    };
+    const shipping: ShippingCalculator = {
+      computeShippingCents: vi.fn().mockReturnValue(500),
+    };
+    const cart = new Cart({
+      discountPolicy: discount,
+      shippingCalculator: shipping,
+    });
+    cart.add(mkProduct("a", 5000), 1);
+
+    const t = cart.totals();
+    expect(shipping.computeShippingCents).toHaveBeenCalledWith(
+      expect.any(Array),
+      3000, // discounted subtotal
+    );
+    expect(t.shippingCents).toBe(500);
+    expect(t.totalCents).toBe(3000 + 500);
+  });
+
+  it("clamps discount to [0, subtotal]", () => {
+    const overDiscount: DiscountPolicy = {
+      computeDiscountCents: vi.fn().mockReturnValue(99999),
+    };
+    const cart = new Cart({ discountPolicy: overDiscount });
+    cart.add(mkProduct("a", 1000), 1);
+    const t = cart.totals();
+    expect(t.discountCents).toBe(1000); // clamped to subtotal
+    expect(t.totalCents).toBe(0);
+  });
+
+  it("clamps negative discount to 0", () => {
+    const negDiscount: DiscountPolicy = {
+      computeDiscountCents: vi.fn().mockReturnValue(-500),
+    };
+    const cart = new Cart({ discountPolicy: negDiscount });
+    cart.add(mkProduct("a", 1000), 1);
+    const t = cart.totals();
+    expect(t.discountCents).toBe(0);
+    expect(t.totalCents).toBe(1000);
+  });
+
+  it("clamps negative tax to 0", () => {
+    const tax: TaxCalculator = {
+      computeTaxCents: vi.fn().mockReturnValue(-100),
+    };
+    const cart = new Cart({ taxCalculator: tax });
+    cart.add(mkProduct("a", 1000), 1);
+    expect(cart.totals().taxCents).toBe(0);
+  });
+
+  it("clamps negative shipping to 0", () => {
+    const shipping: ShippingCalculator = {
+      computeShippingCents: vi.fn().mockReturnValue(-100),
+    };
+    const cart = new Cart({ shippingCalculator: shipping });
+    cart.add(mkProduct("a", 1000), 1);
+    expect(cart.totals().shippingCents).toBe(0);
+  });
+
+  it("uses custom region for tax", () => {
+    const tax: TaxCalculator = {
+      computeTaxCents: vi.fn().mockReturnValue(0),
+    };
+    const cart = new Cart({ taxCalculator: tax, region: "FR" });
+    cart.add(mkProduct("a", 1000), 1);
+    cart.totals();
+    expect(tax.computeTaxCents).toHaveBeenCalledWith(1000, "FR");
